import 'dart:io';

import 'package:fit_dart_sdk/fit_dart_sdk.dart';

/// Decodes a FIT file, prints a summary, then encodes a small activity of its
/// own and reads it back.
///
///     dart run example/fit_dart_sdk_example.dart test/data/Activity.fit
void main(List<String> args) {
  final path = args.isEmpty ? 'test/data/Activity.fit' : args.first;
  final bytes = File(path).readAsBytesSync();

  // decode() never throws: a truncated file still yields everything that
  // decoded before the problem, alongside a description of it.
  final result = FitDecoder(bytes).decode();
  for (final error in result.errors) {
    stderr.writeln('decode error: $error');
  }

  print('$path: ${result.mesgs.length} messages, '
      'profile ${result.profileVersion}');

  for (final session in result.messages.sessionMesgs) {
    print('session: ${session.sport?.name} '
        '${session.totalDistance?.toStringAsFixed(0)} m '
        'in ${session.totalElapsedTime?.toStringAsFixed(0)} s');
  }

  final withHeartRate =
      result.messages.recordMesgs.where((r) => r.heartRate != null).toList();
  if (withHeartRate.isNotEmpty) {
    final mean =
        withHeartRate.map((r) => r.heartRate!).reduce((a, b) => a + b) /
            withHeartRate.length;
    print('mean heart rate: ${mean.toStringAsFixed(1)} bpm '
        'over ${withHeartRate.length} records');
  }

  // Only the first field of each is read here; every message exposes the whole
  // profile, and the untyped API underneath it.
  for (final description in result.messages.developerFieldDescriptions) {
    print('developer field: ${description.fieldName} (${description.units})');
  }

  // ---------------------------------------------------------------- encoding

  final start = DateTime.timestamp();
  final encoded = encodeFit((encoder) {
    encoder.write(FileIdMesg()
      ..type = FitFile.activity
      ..manufacturer = Manufacturer.development
      ..serialNumber = 1234
      ..timeCreated = start);

    for (var i = 0; i < 60; i++) {
      encoder.write(RecordMesg()
        ..timestamp = start.add(Duration(seconds: i))
        ..heartRate = 120 + (i % 20)
        ..distance = i * 3.0
        ..speed = 3.0);
    }

    encoder.write(SessionMesg()
      ..timestamp = start.add(const Duration(seconds: 60))
      ..startTime = start
      ..sport = Sport.running
      ..totalElapsedTime = 60.0
      ..totalDistance = 180.0);
  });

  final again = FitDecoder(encoded).decode();
  print('encoded ${encoded.length} bytes, read back '
      '${again.messages.recordMesgs.length} records');
}
